#Requires -RunAsAdministrator
<#
.SYNOPSIS
    Self-contained Sysmon deployment. Sysmon64.exe and sysmonconfig.xml are
    embedded as base64 - no internet or extra files needed.
.NOTES
    Just copy this single .ps1 to the endpoint and run it as admin.
#>

param(
    [string]$InstallDir = "$env:ProgramFiles\Sysmon",
    [switch]$Update
)

$ErrorActionPreference = 'Stop'

# --- Embedded payloads (base64) ---
$SysmonB64 = @'

'@

$ConfigB64 = @'

'@

# --- Ensure install directory exists ---
if (-not (Test-Path $InstallDir)) {
    Write-Host "[*] Creating install directory: $InstallDir"
    New-Item -ItemType Directory -Path $InstallDir -Force | Out-Null
}

# --- Write embedded files to disk ---
$SysmonExe  = Join-Path $InstallDir 'Sysmon64.exe'
$ConfigFile = Join-Path $InstallDir 'sysmonconfig.xml'

Write-Host "[*] Extracting Sysmon64.exe..."
[IO.File]::WriteAllBytes($SysmonExe, [Convert]::FromBase64String($SysmonB64))

Write-Host "[*] Extracting sysmonconfig.xml..."
[IO.File]::WriteAllBytes($ConfigFile, [Convert]::FromBase64String($ConfigB64))

# --- Free memory ---
Remove-Variable SysmonB64, ConfigB64

# --- Install or Update Sysmon ---
if ($Update) {
    Write-Host "[*] Updating Sysmon config..."
    & $SysmonExe -c $ConfigFile
} else {
    $svc = Get-Service -Name Sysmon64 -ErrorAction SilentlyContinue
    if ($svc) {
        Write-Host "[*] Sysmon service already installed - updating config..."
        & $SysmonExe -c $ConfigFile
    } else {
        Write-Host "[*] Installing Sysmon with sysmon-modular config..."
        & $SysmonExe -accepteula -i $ConfigFile
    }
}

if ($LASTEXITCODE -eq 0) {
    Write-Host "[+] Sysmon deployed successfully."
    Write-Host "[+] Events will appear in: Microsoft-Windows-Sysmon/Operational"
} else {
    Write-Error "[-] Sysmon installation failed with exit code $LASTEXITCODE"
}
